Y,IAClD,CAUO,SAAS4N,EACf4H,EACA5O,EACA6O,GAEA,IACC,OAAO,IAAIC,KAAKC,aAAcF,EAAQ,CACrCG,MAAO,WACPhP,aACGiP,OAAQ1T,OAAQqT,GACrB,CAAE,MACD,MAAO,GAAIA,KAAY5O,GACxB,CACD,CAQO,SAASO,EAAatG,GAC5B,OAASA,GACR,IAAK,UACJ,OAAOpD,EAAAA,EAAAA,IAAI,YAAa,WACzB,IAAK,UACJ,OAAOA,EAAAA,EAAAA,IAAI,iBAAkB,WAC9B,IAAK,SACJ,OAAOA,EAAAA,EAAAA,IAAI,YAAa,WACzB,IAAK,UACJ,OAAOA,EAAAA,EAAAA,IAAI,UAAW,WACvB,IAAK,QACJ,OAAOA,EAAAA,EAAAA,IAAI,UAAW,WACvB,QACC,OAAOA,EAAAA,EAAAA,IAAI,QAAS,WAEvB,CAQO,SAASkQ,EAAYrE,GAC3B,OAASA,GACR,IAAK,aACJ,OAAO7L,EAAAA,EAAAA,IAAI,eAAgB,WAC5B,IAAK,SACJ,OAAOA,EAAAA,EAAAA,IAAI,SAAU,WACtB,IAAK,MACJ,OAAOA,EAAAA,EAAAA,IAAI,aAAc,WAC1B,QACC,OAAOA,EAAAA,EAAAA,IAAI,WAAY,WAE1B,C,8DCttBO,SAAS2P,GAAOC,QACtBA,EAAOC,QACPA,GAAU,EAAKwI,QACfA,GAAU,EAAKC,UACfA,EAAY,GAAErY,SACdA,KACGsY,IAEH,OAAOC,EAAAA,EAAAA,eACN,MACA,CACCF,UAAW,mBACX3V,KAAM,SACN,aAAciN,EACdvF,SAAU,IAEXmO,EAAAA,EAAAA,eACC,QACA,IACID,EACHD,UAAW,CACV,YACAzI,GAAW,oBACXwI,GAAW,oBACXC,GAECG,OAAQ9R,SACR+R,KAAM,OAETF,EAAAA,EAAAA,eAAe,UAAW,KAAM5I,GAChC3P,GAGH,C","sources":["webpack://ohmylmsExtensionSdk/./assets/src/app/components/Pagination.tsx","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/MediaPicker.tsx","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/CourseEditorPage.tsx","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/useCourseEditor.ts","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/useUnsavedChangesGuard.ts","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/useCourses.ts","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/CoursesPage.tsx","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/api.ts","webpack://ohmylmsExtensionSdk/./assets/src/app/features/courses/model.ts","webpack://ohmylmsExtensionSdk/./assets/src/ui/Table.jsx"],"sourcesContent":["import { Button } from '@wordpress/components';\nimport { __, sprintf } from '@wordpress/i18n';\n\nexport function Pagination( {\n\tpage,\n\tpages,\n\tbusy,\n\tonChange,\n}: {\n\tpage: number;\n\tpages: number;\n\tbusy: boolean;\n\tonChange: ( next: number ) => void;\n} ) {\n\treturn (\n\t\t<nav aria-label={ __( 'Pagination', 'ohmylms' ) }>\n\t\t\t<Button\n\t\t\t\tvariant=\"secondary\"\n\t\t\t\tdisabled={ busy || page <= 1 }\n\t\t\t\tonClick={ () => onChange( page - 1 ) }\n\t\t\t>\n\t\t\t\t{ __( 'Previous page', 'ohmylms' ) }\n\t\t\t</Button>{ ' ' }\n\t\t\t<span>\n\t\t\t\t{ sprintf(\n\t\t\t\t\t/* translators: %1$d: current page; %2$d: total pages. */\n\t\t\t\t\t__( 'Page %1$d of %2$d', 'ohmylms' ),\n\t\t\t\t\tpage,\n\t\t\t\t\tMath.max( 1, pages )\n\t\t\t\t) }\n\t\t\t</span>{ ' ' }\n\t\t\t<Button\n\t\t\t\tvariant=\"secondary\"\n\t\t\t\tdisabled={ busy || page >= pages }\n\t\t\t\tonClick={ () => onChange( page + 1 ) }\n\t\t\t>\n\t\t\t\t{ __( 'Next page', 'ohmylms' ) }\n\t\t\t</Button>\n\t\t</nav>\n\t);\n}\n","import { Button, Modal, Notice, TextControl } from '@wordpress/components';\nimport { useEffect, useState } from '@wordpress/element';\nimport { __, sprintf } from '@wordpress/i18n';\nimport { Pagination } from '../../components/Pagination';\nimport { normalizeApiError } from '../../lib/api';\nimport type { Collection } from '../../lib/api/collection';\nimport { listMedia } from './api';\nimport type { MediaImage } from './types';\n\ninterface Props {\n\ttitle: string;\n\tonSelect: ( image: MediaImage ) => void;\n\tonClose: () => void;\n}\n\n// Pick an image from the media library through the core REST route. Only JPEG, PNG, GIF and WebP\n// images are listed; the server verifies the choice again when the template is saved.\nexport function MediaPicker( { title, onSelect, onClose }: Props ) {\n\tconst [ query, setQuery ] = useState( '' );\n\tconst [ search, setSearch ] = useState( '' );\n\tconst [ page, setPage ] = useState( 1 );\n\tconst [ data, setData ] = useState< Collection< MediaImage > >( {\n\t\titems: [],\n\t\ttotal: 0,\n\t\ttotalPages: 0,\n\t} );\n\tconst [ loading, setLoading ] = useState( true );\n\tconst [ error, setError ] = useState< string | null >( null );\n\tuseEffect( () => {\n\t\tconst controller = new AbortController();\n\t\tsetLoading( true );\n\t\tsetError( null );\n\t\tlistMedia( search, page, controller.signal ).then(\n\t\t\t( next ) => {\n\t\t\t\tif ( ! controller.signal.aborted ) {\n\t\t\t\t\tsetData( next );\n\t\t\t\t\tsetLoading( false );\n\t\t\t\t}\n\t\t\t},\n\t\t\t( failure: unknown ) => {\n\t\t\t\tif ( ! controller.signal.aborted ) {\n\t\t\t\t\tsetError( normalizeApiError( failure ).message );\n\t\t\t\t\tsetLoading( false );\n\t\t\t\t}\n\t\t\t}\n\t\t);\n\t\treturn () => controller.abort();\n\t}, [ search, page ] );\n\treturn (\n\t\t<Modal title={ title } onRequestClose={ onClose }>\n\t\t\t<form\n\t\t\t\trole=\"search\"\n\t\t\t\taria-label={ __( 'Search images', 'ohmylms' ) }\n\t\t\t\tonSubmit={ ( event ) => {\n\t\t\t\t\tevent.preventDefault();\n\t\t\t\t\tsetPage( 1 );\n\t\t\t\t\tsetSearch( query );\n\t\t\t\t} }\n\t\t\t>\n\t\t\t\t<TextControl\n\t\t\t\t\tlabel={ __( 'Search images', 'ohmylms' ) }\n\t\t\t\t\tvalue={ query }\n\t\t\t\t\tonChange={ setQuery }\n\t\t\t\t/>\n\t\t\t\t<Button type=\"submit\" variant=\"secondary\" disabled={ loading }>\n\t\t\t\t\t{ __( 'Search', 'ohmylms' ) }\n\t\t\t\t</Button>\n\t\t\t</form>\n\t\t\t{ error && (\n\t\t\t\t<Notice status=\"error\" isDismissible={ false }>\n\t\t\t\t\t{ error }\n\t\t\t\t</Notice>\n\t\t\t) }\n\t\t\t{ loading && (\n\t\t\t\t<p role=\"status\">{ __( 'Loading images…', 'ohmylms' ) }</p>\n\t\t\t) }\n\t\t\t{ ! loading && ! error && ! data.items.length && (\n\t\t\t\t<p>\n\t\t\t\t\t{ __(\n\t\t\t\t\t\t'No images found. Upload JPEG, PNG, GIF or WebP images in the Media Library first.',\n\t\t\t\t\t\t'ohmylms'\n\t\t\t\t\t) }\n\t\t\t\t</p>\n\t\t\t) }\n\t\t\t{ ! loading && data.items.length > 0 && (\n\t\t\t\t<ul aria-label={ __( 'Images', 'ohmylms' ) }>\n\t\t\t\t\t{ data.items.map( ( image ) => (\n\t\t\t\t\t\t<li key={ image.id }>\n\t\t\t\t\t\t\t<Button\n\t\t\t\t\t\t\t\tvariant=\"secondary\"\n\t\t\t\t\t\t\t\tonClick={ () => onSelect( image ) }\n\t\t\t\t\t\t\t\taria-label={ sprintf(\n\t\t\t\t\t\t\t\t\t/* translators: %s: image title. */\n\t\t\t\t\t\t\t\t\t__( 'Use image %s', 'ohmylms' ),\n\t\t\t\t\t\t\t\t\timage.title || String( image.id )\n\t\t\t\t\t\t\t\t) }\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<img\n\t\t\t\t\t\t\t\t\tsrc={ image.thumbnail_url }\n\t\t\t\t\t\t\t\t\talt=\"\"\n\t\t\t\t\t\t\t\t\twidth={ 48 }\n\t\t\t\t\t\t\t\t\theight={ 48 }\n\t\t\t\t\t\t\t\t\tloading=\"lazy\"\n\t\t\t\t\t\t\t\t/>{ ' ' }\n\t\t\t\t\t\t\t\t{ image.title || `#${ image.id }` }\n\t\t\t\t\t\t\t</Button>\n\t\t\t\t\t\t</li>\n\t\t\t\t\t) ) }\n\t\t\t\t</ul>\n\t\t\t) }\n\t\t\t<Pagination\n\t\t\t\tpage={ page }\n\t\t\t\tpages={ data.totalPages }\n\t\t\t\tbusy={ loading }\n\t\t\t\tonChange={ setPage }\n\t\t\t/>\n\t\t\t<Button variant=\"tertiary\" onClick={ onClose }>\n\t\t\t\t{ __( 'Cancel', 'ohmylms' ) }\n\t\t\t</Button>\n\t\t</Modal>\n\t);\n}\n","import {\n\tButton,\n\tCheckboxControl,\n\tModal,\n\tNotice,\n\tSelectControl,\n\tTextControl,\n\tTextareaControl,\n} from '@wordpress/components';\nimport { useEffect, useRef, useState } from '@wordpress/element';\nimport { __, sprintf } from '@wordpress/i18n';\nimport { Link, useParams } from 'react-router-dom';\nimport { normalizeApiError } from '../../lib/api';\nimport { updateCourse } from './api';\nimport { MediaPicker } from './MediaPicker';\nimport {\n\tformFromCourse,\n\tisDirty,\n\tisValid,\n\tLEVELS,\n\tserverFieldError,\n\tstatusLabel,\n\ttoInput,\n\tvalidateForm,\n} from './model';\nimport { useCourseEditor } from './useCourseEditor';\nimport { useUnsavedChangesGuard } from './useUnsavedChangesGuard';\nimport type {\n\tAccessType,\n\tFormErrors,\n\tFormState,\n\tLevel,\n\tOption,\n\tPriceType,\n\tWritableStatus,\n} from './types';\n\nfunction routeId( value: string | undefined ): number | null {\n\treturn value && /^[1-9]\\d*$/.test( value ) ? Number( value ) : null;\n}\n\nfunction FieldError( { id, message }: { id: string; message?: string } ) {\n\treturn message ? (\n\t\t<p id={ id } role=\"alert\">\n\t\t\t{ message }\n\t\t</p>\n\t) : null;\n}\n\n/**\n * Add the current status to the choices when the user may not pick it (so the select still shows it).\n *\n * @param choices Statuses the user may set.\n * @param current Status of the form.\n * @return The choices to render.\n */\nfunction withCurrentStatus(\n\tchoices: Option[],\n\tcurrent: WritableStatus\n): Option[] {\n\tif ( choices.some( ( option ) => option.value === current ) ) {\n\t\treturn choices;\n\t}\n\treturn [ ...choices, { value: current, label: statusLabel( current ) } ];\n}\n\nfunction pick< T extends string >(\n\tvalue: string,\n\tchoices: readonly T[],\n\tfallback: T\n): T {\n\treturn choices.find( ( choice ) => choice === value ) ?? fallback;\n}\n\nconst WRITABLE: readonly WritableStatus[] = [\n\t'draft',\n\t'pending',\n\t'publish',\n\t'future',\n\t'private',\n];\n\n/**\n * Course settings editor (`#/courses/<id>`): basics, thumbnail, pricing and sale schedule, access,\n * availability and capacity. The curriculum is built in the classic builder, linked at the top. Edits\n * survive failed saves, and leaving with unsaved changes asks first.\n */\nexport default function CourseEditorPage() {\n\tconst params = useParams();\n\tconst id = routeId( params.id );\n\tconst editor = useCourseEditor( id );\n\tconst [ form, setForm ] = useState< FormState | null >( null );\n\tconst [ saved, setSaved ] = useState< FormState | null >( null );\n\tconst [ errors, setErrors ] = useState< FormErrors >( {} );\n\tconst [ busy, setBusy ] = useState( false );\n\tconst [ message, setMessage ] = useState< string | null >( null );\n\tconst [ failure, setFailure ] = useState< string | null >( null );\n\tconst [ picking, setPicking ] = useState( false );\n\tconst [ reveal, setReveal ] = useState( false );\n\tconst summary = useRef< HTMLDivElement >( null );\n\tconst operation = useRef< AbortController | null >( null );\n\tconst dirty = Boolean( form && saved && isDirty( form, sa